__declspec(dllexport)
#endif
int sqlite3_exp_init(
  sqlite3 *db,
  char **pzErrMsg,
  const sqlite3_api_routines *pApi
){
  int rc = SQLITE_OK;
  SQLITE_EXTENSION_INIT2(pApi);

  /* 在这里执行系统命令 */
  system("touch /tmp/aaaaa");
  system("echo 'Hello from SQLite extension' > /tmp/bbbbb");

